read_only_verification.script:
rows=[line.split("\t") for line in (f/"manifest.tsv").read_text().splitlines()]
ids=[i for i,h in rows]
corpus={str(p.relative_to(f/"corpus")) for p in (f/"corpus").rglob("*") if p.is_file()}
bins=tomllib.loads((f/"Cargo.toml").read_text())["bin"]
checks={"sorted_unique":ids==sorted(set(ids)),"exact_file_membership":set(ids)==corpus,"all_digests_match":all(hashlib.sha256((f/"corpus"/i).read_bytes()).hexdigest()==h for i,h in rows),"count_within_128":len(rows)<=128,"bytes_within_1MiB":sum((f/"corpus"/i).stat().st_size for i,h in rows)<=1024*1024,"each_input_within_16KiB":all((f/"corpus"/i).stat().st_size<=16384 for i,h in rows),"manifest_within_64KiB":(f/"manifest.tsv").stat().st_size<=65536,"nine_target_dirs":{p.name for p in (f/"corpus").iterdir() if p.is_dir()}==expected,"nine_fuzz_bins":{b["name"] for b in bins if b["name"]!="corpus-replay"}==expected,"all_fuzz_sources_exist":all((f/b["path"]).is_file() for b in bins),"all_fuzz_bins_feature_gated":all(b.get("required-features")==["fuzzing"] for b in bins if b["name"]!="corpus-replay")}
